/**
 * @sdd
 * [Objetivo]: Controlador REST para la administración y CRUD de cuentas de usuario por parte de administradores (SDD-005-USER-MODULES-AND-ADMIN).
 * [I/O]: Expone rutas bajo /admin/users (GET, POST, GET :id, PUT :id, PATCH :id/status, DELETE :id).
 * [Edge Cases]: Protegido estrictamente con JwtAuthGuard y RolesGuard(ADMIN), previene auto-eliminación.
 */

// backend/src/modules/admin/controllers/admin-users.controller.ts

import {
  Controller,
  Get,
  Post,
  Put,
  Patch,
  Delete,
  Body,
  Param,
  Query,
  UseGuards,
} from '@nestjs/common';
import { JwtAuthGuard } from '../../auth/guards/jwt-auth.guard.js';
import { RolesGuard } from '../../auth/guards/roles.guard.js';
import { Roles } from '../../auth/decorators/roles.decorator.js';
import { CurrentUser } from '../../auth/decorators/current-user.decorator.js';
import { User, UserRole } from '../../users/entities/user.entity.js';
import { AdminUsersService } from '../services/admin-users.service.js';
import {
  AdminCreateUserDto,
  AdminUpdateUserDto,
  AdminUserQueryDto,
} from '../dto/admin-user.dto.js';

/**
 *
 */
@Controller('admin/users')
@UseGuards(JwtAuthGuard, RolesGuard)
@Roles(UserRole.ADMIN)
export class AdminUsersController {
  /**
   *
   * @param adminUsersService
   */
  constructor(private readonly adminUsersService: AdminUsersService) {}

  /**
   *
   * @param query
   */
  @Get()
  async getUsers(@Query() query: AdminUserQueryDto): Promise<User[]> {
    return this.adminUsersService.getUsers(query);
  }

  /**
   *
   * @param dto
   */
  @Post()
  async createUser(@Body() dto: AdminCreateUserDto): Promise<User> {
    return this.adminUsersService.createUser(dto);
  }

  /**
   *
   * @param id
   */
  @Get(':id')
  async getUserById(@Param('id') id: string): Promise<User> {
    return this.adminUsersService.getUserById(id);
  }

  /**
   *
   * @param id
   * @param dto
   */
  @Put(':id')
  async updateUser(
    @Param('id') id: string,
    @Body() dto: AdminUpdateUserDto,
  ): Promise<User> {
    return this.adminUsersService.updateUser(id, dto);
  }

  /**
   *
   * @param id
   */
  @Patch(':id/status')
  async toggleUserStatus(@Param('id') id: string): Promise<User> {
    return this.adminUsersService.toggleUserStatus(id);
  }

  /**
   *
   * @param id
   * @param adminId
   */
  @Delete(':id')
  async deleteUser(
    @Param('id') id: string,
    @CurrentUser('id') adminId: string,
  ): Promise<{ /**
   *
   */
  success: boolean; /**
   *
   */
  message: string }> {
    return this.adminUsersService.deleteUser(id, adminId);
  }
}

/**
 * @sdd
 * [Objetivo]: Servicio de administración de cuentas de usuario con roles RBAC y control de acceso (SDD-005-USER-MODULES-AND-ADMIN).
 * [I/O]: Inyecta Repository<User>. Métodos: getUsers, getUserById, createUser, updateUser, toggleUserStatus, deleteUser.
 * [Edge Cases]: Encriptación segura con bcrypt, unicidad de correo, prevención de auto-eliminación del administrador activo.
 */

// backend/src/modules/admin/services/admin-users.service.ts

import {
  BadRequestException,
  ConflictException,
  Injectable,
  NotFoundException,
} from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import * as bcrypt from 'bcrypt';
import { User, UserStatus } from '../../users/entities/user.entity.js';
import {
  AdminCreateUserDto,
  AdminUpdateUserDto,
  AdminUserQueryDto,
} from '../dto/admin-user.dto.js';

/**
 *
 */
@Injectable()
export class AdminUsersService {
  /**
   *
   * @param userRepository
   */
  constructor(
    @InjectRepository(User)
    private readonly userRepository: Repository<User>,
  ) {}

  /**
   * Obtiene la lista de usuarios del sistema con filtros opcionales de búsqueda, rol y estado.
   * @param query Criterios de filtrado.
   * @returns Lista de usuarios.
   */
  async getUsers(query: AdminUserQueryDto): Promise<User[]> {
    const qb = this.userRepository.createQueryBuilder('user').orderBy('user.createdAt', 'DESC');

    if (query.search && query.search.trim().length > 0) {
      qb.andWhere(
        '(LOWER(user.fullName) LIKE :search OR LOWER(user.email) LIKE :search)',
        { search: `%${query.search.toLowerCase().trim()}%` },
      );
    }

    if (query.role) {
      qb.andWhere('user.role = :role', { role: query.role });
    }

    if (query.status) {
      qb.andWhere('user.status = :status', { status: query.status });
    }

    return qb.getMany();
  }

  /**
   * Obtiene un usuario específico por su ID.
   * @param id UUID del usuario.
   * @returns Entidad User.
   * @throws NotFoundException si no existe.
   */
  async getUserById(id: string): Promise<User> {
    const user = await this.userRepository.findOne({ where: { id } });
    if (!user) {
      throw new NotFoundException(`Usuario con ID ${id} no encontrado.`);
    }
    return user;
  }

  /**
   * Crea un usuario de forma manual asignando credenciales y rol.
   * @param dto Datos del usuario a crear.
   * @returns Usuario persistido.
   * @throws ConflictException si el email ya se encuentra registrado.
   */
  async createUser(dto: AdminCreateUserDto): Promise<User> {
    const emailNormalized = dto.email.toLowerCase().trim();
    const existing = await this.userRepository.findOne({
      where: { email: emailNormalized },
    });

    if (existing) {
      throw new ConflictException(`El correo electrónico ${emailNormalized} ya está registrado.`);
    }

    const saltRounds = 10;
    const passwordHash = await bcrypt.hash(dto.password, saltRounds);

    const newUser = this.userRepository.create({
      email: emailNormalized,
      passwordHash,
      fullName: dto.fullName.trim(),
      role: dto.role,
      status: UserStatus.ACTIVE,
      phone: dto.phone ?? null,
      avatarUrl: dto.avatarUrl ?? null,
    });

    return this.userRepository.save(newUser);
  }

  /**
   * Actualiza los datos de un usuario existente.
   * @param id UUID del usuario a actualizar.
   * @param dto Campos a modificar.
   * @returns Usuario actualizado.
   */
  async updateUser(id: string, dto: AdminUpdateUserDto): Promise<User> {
    const user = await this.getUserById(id);

    if (dto.fullName !== undefined) {
      user.fullName = dto.fullName.trim();
    }
    if (dto.phone !== undefined) {
      user.phone = dto.phone ?? null;
    }
    if (dto.role !== undefined) {
      user.role = dto.role;
    }
    if (dto.status !== undefined) {
      user.status = dto.status;
    }
    if (dto.avatarUrl !== undefined) {
      user.avatarUrl = dto.avatarUrl ?? null;
    }

    return this.userRepository.save(user);
  }

  /**
   * Alterna el estado de una cuenta de usuario entre ACTIVE e INACTIVE.
   * @param id UUID del usuario.
   * @returns Usuario con estado actualizado.
   */
  async toggleUserStatus(id: string): Promise<User> {
    const user = await this.getUserById(id);
    user.status = user.status === UserStatus.ACTIVE ? UserStatus.INACTIVE : UserStatus.ACTIVE;
    return this.userRepository.save(user);
  }

  /**
   * Elimina permanentemente una cuenta de usuario.
   * @param id UUID del usuario a eliminar.
   * @param currentAdminId ID del administrador que ejecuta la operación para prevenir auto-eliminación.
   * @returns Confirmación de eliminación.
   */
  async deleteUser(id: string, currentAdminId: string): Promise<{ /**
   *
   */
  success: boolean; /**
   *
   */
  message: string }> {
    if (id === currentAdminId) {
      throw new BadRequestException('No puedes eliminar tu propia cuenta de administrador activa.');
    }

    const user = await this.getUserById(id);
    await this.userRepository.remove(user);
    return { success: true, message: `Usuario ${user.email} eliminado exitosamente.` };
  }
}

/**
 * @sdd
 * [Objetivo]: Controlador REST para autenticacion y verificacion de sesion (SDD-002-AUTH-RBAC).
 * [I/O]: POST /api/v1/auth/login, GET /api/v1/auth/profile.
 * [Edge Cases]: Zero auto-registration, decoradores OpenAPI completos, codigos HTTP estrictos (200, 400, 401, 403).
 */

import { Controller, Post, Body, HttpCode, HttpStatus, Get, UseGuards } from '@nestjs/common';
import { ApiTags, ApiOperation, ApiResponse, ApiBearerAuth } from '@nestjs/swagger';
import { AuthService, AuthSuccessPayload } from './auth.service.js';
import { LoginDto } from './dto/login.dto.js';
import { RefreshTokenDto } from './dto/refresh-token.dto.js';
import { JwtAuthGuard } from './guards/jwt-auth.guard.js';
import { CurrentUser } from './decorators/current-user.decorator.js';
import { User } from '../users/entities/user.entity.js';

/**
 *
 */
@ApiTags('Auth')
@Controller('auth')
export class AuthController {
  /**
   *
   * @param authService
   */
  constructor(private readonly authService: AuthService) {}

  /**
   * Endpoint de inicio de sesion estricto sin auto-registro.
   * @param loginDto Credenciales validadas via ValidationPipe.
   * @returns Token JWT y datos del usuario.
   */
  @Post('login')
  @HttpCode(HttpStatus.OK)
  @ApiOperation({
    summary: 'Iniciar sesion de usuario',
    description: 'Valida credenciales con email RFC 5322 y contraseña minima de 6 caracteres. Emite JWT.',
  })
  @ApiResponse({
    status: 200,
    description: 'Autenticación exitosa. Retorna JWT Bearer y perfil de usuario.',
  })
  @ApiResponse({
    status: 400,
    description: 'Formato de credenciales inválido (ValidationPipe error).',
  })
  @ApiResponse({
    status: 401,
    description: 'Credenciales inválidas (anti-enumeración).',
  })
  @ApiResponse({
    status: 403,
    description: 'Cuenta suspendida o inactiva.',
  })
  async login(@Body() loginDto: LoginDto): Promise<AuthSuccessPayload> {
    return this.authService.login(loginDto);
  }

  /**
   * Endpoint para la renovacion silenciosa de tokens JWT de sesion.
   * @param refreshTokenDto DTO con el refresh token emitido previamente.
   * @returns Nuevo par de tokens y datos de usuario.
   */
  @Post('refresh')
  @HttpCode(HttpStatus.OK)
  @ApiOperation({
    summary: 'Renovar sesion con refresh token',
    description: 'Valida el refresh token criptografico y emite un nuevo par de tokens para evitar la perdida de sesion en ruta.',
  })
  @ApiResponse({
    status: 200,
    description: 'Sesión renovada exitosamente.',
  })
  @ApiResponse({
    status: 401,
    description: 'Refresh token expirado o inválido.',
  })
  @ApiResponse({
    status: 403,
    description: 'Cuenta suspendida o inactiva.',
  })
  async refresh(@Body() refreshTokenDto: RefreshTokenDto): Promise<AuthSuccessPayload> {
    return this.authService.refreshToken(refreshTokenDto);
  }

  /**
   * Obtiene los datos del usuario autenticado segun el Bearer Token enviado.
   * @param user Usuario inyectado por JwtStrategy.
   * @returns Datos del usuario.
   */
  @Get('profile')
  @UseGuards(JwtAuthGuard)
  @ApiBearerAuth()
  @ApiOperation({ summary: 'Obtener perfil del usuario autenticado' })
  @ApiResponse({ status: 200, description: 'Perfil recuperado exitosamente.' })
  @ApiResponse({ status: 401, description: 'No autorizado / Token ausente o invalido.' })
  getProfile(@CurrentUser() user: User): User {
    return user;
  }
}

/**
 * @sdd
 * [Objetivo]: Servicio principal de autenticacion, emision de JWT y RBAC (SDD-002-AUTH-RBAC).
 * [I/O]: Entrada: LoginDto. Salida: AuthResponse con accessToken y datos de usuario sanitizados.
 * [Edge Cases]: Mitigacion de ataques de enumeracion con 401 generico, verificacion de estado inactivo con 403, bcrypt 10 rounds.
 */

import { Injectable, UnauthorizedException, ForbiddenException, Logger } from '@nestjs/common';
import { JwtService } from '@nestjs/jwt';
import { ConfigService } from '@nestjs/config';
import * as bcrypt from 'bcrypt';
import { UsersService } from '../users/users.service.js';
import { LoginDto } from './dto/login.dto.js';
import { RefreshTokenDto } from './dto/refresh-token.dto.js';
import { User, UserStatus } from '../users/entities/user.entity.js';

/**
 *
 */
export interface AuthSuccessPayload {
  /**
   *
   */
  accessToken: string;
  /**
   *
   */
  refreshToken: string;
  /**
   *
   */
  user: {
    /**
     *
     */
    id: string;
    /**
     *
     */
    email: string;
    /**
     *
     */
    fullName: string;
    /**
     *
     */
    role: string;
    /**
     *
     */
    status: UserStatus;
    /**
     *
     */
    phone?: string | null;
    /**
     *
     */
    avatarUrl?: string | null;
  };
}

/**
 * Par de tokens emitidos para autenticacion y renovacion silenciosa.
 */
export interface AuthTokenPair {
  /**
   * Token de acceso JWT de corta vigencia.
   */
  accessToken: string;
  /**
   * Token de renovacion JWT de larga vigencia.
   */
  refreshToken: string;
}

/**
 * Carga util decodificada del token de renovacion JWT.
 */
export interface RefreshTokenJwtPayload {
  /**
   * Identificador UUID del usuario.
   */
  sub: string;
  /**
   * Indicador del tipo de token.
   */
  tokenType?: string;
}

/**
 * Servicio encargado de la logica de negocio para inicio de sesion y verificacion de credenciales.
 */
@Injectable()
export class AuthService {
  /**
   *
   */
  private readonly logger = new Logger(AuthService.name);

  /**
   *
   * @param usersService
   * @param jwtService
   * @param configService
   */
  constructor(
    private readonly usersService: UsersService,
    private readonly jwtService: JwtService,
    private readonly configService: ConfigService,
  ) {}

  /**
   * Obtiene la clave secreta para la firma y verificacion de tokens de renovacion.
   * @returns Secreto de refresh token.
   */
  private getRefreshSecret(): string {
    return (
      this.configService.get<string>('JWT_REFRESH_SECRET') ||
      `${this.configService.get<string>('JWT_SECRET')}__refresh`
    );
  }

  /**
   * Obtiene el tiempo de expiracion configurado para los refresh tokens.
   * @returns Tiempo en formato string (ej: 30d).
   */
  private getRefreshExpiresIn(): string {
    return this.configService.get<string>('JWT_REFRESH_EXPIRATION') || '30d';
  }

  /**
   * Genera el par criptografico de tokens (accessToken y refreshToken).
   * @param user Entidad de usuario autenticada.
   * @returns Objeto con accessToken y refreshToken.
   */
  private generateTokens(user: User): AuthTokenPair {
    const payload = {
      sub: user.id,
      email: user.email,
      role: user.role,
      fullName: user.fullName,
    };

    const accessToken = this.jwtService.sign(payload);
    const refreshToken = this.jwtService.sign(
      { sub: user.id, tokenType: 'refresh' },
      {
        secret: this.getRefreshSecret(),
        expiresIn: this.getRefreshExpiresIn() as unknown as number,
      },
    );

    return { accessToken, refreshToken };
  }

  /**
   * Autentica un usuario verificando correo y contraseña con mitigacion de ataques de enumeracion.
   * @param loginDto Credenciales de acceso (email y password).
   * @returns Token de acceso JWT, refresh token y objeto de usuario seguro.
   * @throws UnauthorizedException si las credenciales son invalidas o el usuario no existe.
   * @throws ForbiddenException si el usuario se encuentra en estado inactivo.
   */
  async login(loginDto: LoginDto): Promise<AuthSuccessPayload> {
    const { email, password } = loginDto;

    // Busqueda con seleccion explicita de passwordHash
    const user = await this.usersService.findByEmailWithPassword(email);

    // Resistencia a enumeracion: mensaje generico identico para usuario inexistente o password incorrecto
    if (!user || !user.passwordHash) {
      this.logger.warn(`Intento de login fallido para cuenta no registrada: ${email}`);
      throw new UnauthorizedException('Credenciales inválidas');
    }

    const isPasswordValid = await bcrypt.compare(password, user.passwordHash);
    if (!isPasswordValid) {
      this.logger.warn(`Intento de login con contraseña incorrecta para: ${email}`);
      throw new UnauthorizedException('Credenciales inválidas');
    }

    // Validacion de estado de la cuenta
    if (user.status !== UserStatus.ACTIVE) {
      this.logger.warn(`Intento de inicio de sesion bloqueado por estado ${user.status} en: ${email}`);
      throw new ForbiddenException('Cuenta suspendida o inactiva');
    }

    const tokens = this.generateTokens(user);

    return {
      accessToken: tokens.accessToken,
      refreshToken: tokens.refreshToken,
      user: {
        id: user.id,
        email: user.email,
        fullName: user.fullName,
        role: user.role,
        status: user.status,
        phone: user.phone,
        avatarUrl: user.avatarUrl,
      },
    };
  }

  /**
   * Renueva las credenciales del usuario validando criptograficamente el refresh token.
   * @param dto DTO con el refreshToken a validar.
   * @returns Nuevo par de tokens y datos de usuario.
   * @throws UnauthorizedException si el token es invalido, expirado o el usuario ya no existe.
   * @throws ForbiddenException si la cuenta del usuario fue desactivada.
   */
  async refreshToken(dto: RefreshTokenDto): Promise<AuthSuccessPayload> {
    try {
      const decoded = await this.jwtService.verifyAsync<RefreshTokenJwtPayload>(
        dto.refreshToken,
        {
          secret: this.getRefreshSecret(),
        },
      );

      if (decoded.tokenType !== 'refresh' || !decoded.sub) {
        throw new UnauthorizedException('Token de renovación inválido');
      }

      const user = await this.usersService.findById(decoded.sub);
      if (!user) {
        throw new UnauthorizedException('Usuario no encontrado');
      }

      if (user.status !== UserStatus.ACTIVE) {
        throw new ForbiddenException('Cuenta suspendida o inactiva');
      }

      const tokens = this.generateTokens(user);

      return {
        accessToken: tokens.accessToken,
        refreshToken: tokens.refreshToken,
        user: {
          id: user.id,
          email: user.email,
          fullName: user.fullName,
          role: user.role,
          status: user.status,
          phone: user.phone,
          avatarUrl: user.avatarUrl,
        },
      };
    } catch (error) {
      if (error instanceof ForbiddenException) {
        throw error;
      }
      this.logger.warn(`Fallo en renovación de token: ${(error as Error).message}`);
      throw new UnauthorizedException('Refresh token expirado o inválido');
    }
  }

  /**
   * Valida un usuario por ID devolviendo la entidad sin la contraseña.
   * @param id Identificador UUID.
   * @returns Entidad User.
   */
  async validateUserById(id: string): Promise<User> {
    return this.usersService.findById(id);
  }
}

/**
 * @sdd
 * [Objetivo]: Guard de autorizacion RBAC basado en roles (SDD-002-AUTH-RBAC).
 * [I/O]: Entrada: ExecutionContext y metadatos de roles. Salida: boolean o excepcion 403 Forbidden.
 * [Edge Cases]: Permite paso libre si el endpoint no tiene decorador @Roles, bloquea si el rol del usuario no coincide.
 */

import { Injectable, CanActivate, ExecutionContext, ForbiddenException } from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import { ROLES_KEY } from '../decorators/roles.decorator.js';
import { UserRole, User } from '../../users/entities/user.entity.js';

/**
 *
 */
@Injectable()
export class RolesGuard implements CanActivate {
  /**
   *
   * @param reflector
   */
  constructor(private readonly reflector: Reflector) {}

  /**
   * Determina si el usuario autenticado posee al menos uno de los roles autorizados.
   * @param context Contexto de ejecucion de la peticion HTTP.
   * @returns true si tiene permiso.
   * @throws ForbiddenException si el rol no coincide.
   */
  canActivate(context: ExecutionContext): boolean {
    const requiredRoles = this.reflector.getAllAndOverride<UserRole[]>(ROLES_KEY, [
      context.getHandler(),
      context.getClass(),
    ]);

    if (!requiredRoles || requiredRoles.length === 0) {
      return true;
    }

    const request = context.switchToHttp().getRequest<{ /**
     *
     */
    user?: User }>();
    const user = request.user;

    if (!user || !user.role) {
      throw new ForbiddenException('Acceso restringido: no se encontro el rol del usuario');
    }

    const hasRole = requiredRoles.includes(user.role);
    if (!hasRole) {
      throw new ForbiddenException(
        `Acceso denegado: se requiere uno de los roles [${requiredRoles.join(', ')}]`,
      );
    }

    return true;
  }
}

/**
 * @sdd
 * [Objetivo]: Controlador REST para la gestión de fichas médicas de excursionistas y confirmación de asistencia (SDD-005-USER-MODULES-AND-ADMIN).
 * [I/O]: Expone endpoints GET y POST bajo /medical-profile. Consume MedicalService y extrae usuario con @CurrentUser.
 * [Edge Cases]: Validación con JwtAuthGuard para usuarios y RolesGuard(ADMIN) para inspección por parte de guías.
 */

// backend/src/modules/medical/medical.controller.ts

import {
  Controller,
  Get,
  Post,
  Body,
  Param,
  UseGuards,
  NotFoundException,
} from '@nestjs/common';
import { JwtAuthGuard } from '../auth/guards/jwt-auth.guard.js';
import { RolesGuard } from '../auth/guards/roles.guard.js';
import { Roles } from '../auth/decorators/roles.decorator.js';
import { CurrentUser } from '../auth/decorators/current-user.decorator.js';
import { User, UserRole } from '../users/entities/user.entity.js';
import { MedicalService } from './medical.service.js';
import { SaveMedicalProfileDto } from './dto/save-medical-profile.dto.js';
import { MedicalProfile } from './entities/medical-profile.entity.js';

/**
 *
 */
@Controller('medical-profile')
@UseGuards(JwtAuthGuard)
export class MedicalController {
  /**
   *
   * @param medicalService
   */
  constructor(private readonly medicalService: MedicalService) {}

  /**
   * Obtiene la ficha médica del usuario actualmente autenticado.
   * @param user Usuario extraído del token JWT.
   * @returns Ficha médica del usuario o null si no existe.
   */
  @Get()
  async getMyProfile(@CurrentUser() user: User): Promise<MedicalProfile | null> {
    return this.medicalService.getProfileByUserId(user.id);
  }

  /**
   * Registra o actualiza la ficha médica y confirmación de asistencia del usuario autenticado.
   * @param user Usuario autenticado.
   * @param dto Datos médicos y de asistencia validados.
   * @returns Ficha médica persistida.
   */
  @Post()
  async saveMyProfile(
    @CurrentUser() user: User,
    @Body() dto: SaveMedicalProfileDto,
  ): Promise<MedicalProfile> {
    return this.medicalService.saveProfile(user.id, dto);
  }

  /**
   * Permite a los guías y administradores consultar la ficha médica de un excursionista específico.
   * @param userId UUID del usuario a consultar.
   * @returns Ficha médica encontrada.
   * @throws NotFoundException si el usuario no tiene ficha médica registrada.
   */
  @Get(':userId')
  @UseGuards(RolesGuard)
  @Roles(UserRole.ADMIN)
  async getProfileByUserId(@Param('userId') userId: string): Promise<MedicalProfile> {
    const profile = await this.medicalService.getProfileByUserId(userId);
    if (!profile) {
      throw new NotFoundException(`Ficha médica para el usuario ${userId} no encontrada.`);
    }
    return profile;
  }
}

/**
 * @sdd
 * [Objetivo]: Servicio de lógica de negocio para la gestión de fichas médicas y confirmación de asistencia (SDD-005-USER-MODULES-AND-ADMIN).
 * [I/O]: Inyecta Repository<MedicalProfile>. Métodos getProfileByUserId(userId) y saveProfile(userId, dto).
 * [Edge Cases]: Operación de upsert idempotente según la existencia previa de la ficha médica para el usuario.
 */

// backend/src/modules/medical/medical.service.ts

import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { MedicalProfile } from './entities/medical-profile.entity.js';
import { SaveMedicalProfileDto } from './dto/save-medical-profile.dto.js';

/**
 *
 */
@Injectable()
export class MedicalService {
  /**
   *
   * @param medicalProfileRepository
   */
  constructor(
    @InjectRepository(MedicalProfile)
    private readonly medicalProfileRepository: Repository<MedicalProfile>,
  ) {}

  /**
   * Obtiene la ficha médica de un usuario por su identificador único.
   * @param userId Identificador UUID del usuario.
   * @returns Ficha médica encontrada o null si no se ha registrado.
   */
  async getProfileByUserId(userId: string): Promise<MedicalProfile | null> {
    return this.medicalProfileRepository.findOne({
      where: { userId },
    });
  }

  /**
   * Guarda o actualiza la ficha médica de un usuario de forma idempotente.
   * @param userId Identificador UUID del usuario.
   * @param dto Datos médicos y de asistencia validados.
   * @returns Ficha médica creada o actualizada.
   */
  async saveProfile(userId: string, dto: SaveMedicalProfileDto): Promise<MedicalProfile> {
    let profile = await this.medicalProfileRepository.findOne({
      where: { userId },
    });

    if (!profile) {
      profile = this.medicalProfileRepository.create({
        userId,
        ...dto,
      });
    } else {
      profile.attendanceConfirmed = dto.attendanceConfirmed;
      profile.medicalConditions = dto.medicalConditions ?? null;
      profile.allergies = dto.allergies ?? null;
      profile.medications = dto.medications ?? null;
      profile.dietType = dto.dietType;
      profile.emergencyContactName = dto.emergencyContactName ?? null;
      profile.emergencyContactPhone = dto.emergencyContactPhone ?? null;
      profile.bloodType = dto.bloodType ?? null;
      profile.notes = dto.notes ?? null;
    }

    return this.medicalProfileRepository.save(profile);
  }
}

/**
 * @sdd
 * [Objetivo]: Servicio de gestion de estado volatil y telemetria en memoria rapida Redis (SDD-003-TELEMETRY-REALTIME).
 * [I/O]: Expone metodos saveUserLocation, getAllLiveLocations y removeUserLocation usando comandos GEOADD y TTL de 10 min.
 * [Edge Cases]: Reconexion automatica ante caida del contenedor Redis, control de excepciones sin bloquear el hilo WebSocket.
 */

import { Injectable, OnModuleDestroy, Logger } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { Redis } from 'ioredis';

/**
 *
 */
export interface RedisTelemetryPayload {
  /**
   *
   */
  userId: string;
  /**
   *
   */
  fullName: string;
  /**
   *
   */
  role: string;
  /**
   *
   */
  latitude: number;
  /**
   *
   */
  longitude: number;
  /**
   *
   */
  altitude?: number | null;
  /**
   *
   */
  accuracy?: number | null;
  /**
   *
   */
  speed?: number | null;
  /**
   *
   */
  heading?: number | null;
  /**
   *
   */
  batteryLevel?: number | null;
  /**
   *
   */
  isSos?: boolean;
  /**
   *
   */
  sosMessage?: string | null;
  /**
   *
   */
  timestamp: number;
}

/**
 * Servicio encargado de la interaccion directa con el cluster o instancia de Redis.
 */
@Injectable()
export class RedisService implements OnModuleDestroy {
  /**
   *
   */
  private readonly logger = new Logger(RedisService.name);
  /**
   *
   */
  private readonly client: Redis;

  /**
   *
   */
  private readonly TTL_SECONDS = 600; // 10 minutos
  /**
   *
   */
  private readonly GEO_KEY = 'live_locations';

  /**
   *
   * @param configService
   */
  constructor(private readonly configService: ConfigService) {
    const host = this.configService.get<string>('REDIS_HOST', 'localhost');
    const port = this.configService.get<number>('REDIS_PORT', 6379);

    this.client = new Redis({
      host,
      port,
      lazyConnect: false,
      /**
       *
       * @param times
       */
      retryStrategy: (times) => Math.min(times * 100, 3000),
    });

    this.client.on('connect', () => {
      this.logger.log(`Conexión establecida con Redis en ${host}:${port}`);
    });

    this.client.on('error', (err) => {
      this.logger.error(`Error en cliente Redis: ${err.message}`);
    });
  }

  /**
   * Guarda o actualiza la coordenada de un usuario en Redis con TTL de 10 minutos y actualiza el indice GEO.
   * @param payload Datos de telemetria del usuario.
   */
  async saveUserLocation(payload: RedisTelemetryPayload): Promise<void> {
    try {
      const key = `user:location:${payload.userId}`;
      const serialized = JSON.stringify(payload);

      // Hot State: Guardar clave individual con TTL de 10 minutos
      await this.client.set(key, serialized, 'EX', this.TTL_SECONDS);

      // Indice geoespacial en vivo: GEOADD live_locations <lng> <lat> <member>
      await this.client.geoadd(this.GEO_KEY, payload.longitude, payload.latitude, payload.userId);
    } catch (error) {
      this.logger.error(`Error al persistir telemetria en Redis: ${(error as Error).message}`);
    }
  }

  /**
   * Obtiene la fotografia instantanea de todas las ubicaciones activas actualmente en memoria.
   * @returns Lista de telemetrias activas.
   */
  async getAllLiveLocations(): Promise<RedisTelemetryPayload[]> {
    try {
      const keys = await this.client.keys('user:location:*');
      if (keys.length === 0) {
        return [];
      }

      const rawValues = await this.client.mget(keys);
      const results: RedisTelemetryPayload[] = [];

      for (const val of rawValues) {
        if (val) {
          try {
            results.push(JSON.parse(val) as RedisTelemetryPayload);
          } catch {
            // Omitir valor invalido
          }
        }
      }

      return results;
    } catch (error) {
      this.logger.error(`Error al obtener snapshot de ubicaciones en Redis: ${(error as Error).message}`);
      return [];
    }
  }

  /**
   * Elimina un usuario del estado activo en Redis.
   * @param userId UUID del usuario.
   */
  async removeUserLocation(userId: string): Promise<void> {
    try {
      await this.client.del(`user:location:${userId}`);
      await this.client.zrem(this.GEO_KEY, userId);
    } catch (error) {
      this.logger.error(`Error al remover usuario de Redis: ${(error as Error).message}`);
    }
  }

  /**
   * Cierra ordenadamente la conexion con Redis al detener la aplicacion.
   */
  onModuleDestroy(): void {
    this.client.disconnect();
  }
}

/**
 * @sdd
 * [Objetivo]: Servicio de gestion y persistencia de usuarios (SDD-002-AUTH-RBAC).
 * [I/O]: Inyecta Repository<User>, expone busqueda por email (con o sin passwordHash) y por ID.
 * [Edge Cases]: Sanitizacion de datos, busquedas seguras con QueryBuilder para evitar filtracion de hashes.
 */

import { Injectable, NotFoundException } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { User } from './entities/user.entity.js';

/**
 * Servicio encargado de la consulta y persistencia de la entidad User.
 */
@Injectable()
export class UsersService {
  /**
   *
   * @param userRepository
   */
  constructor(
    @InjectRepository(User)
    private readonly userRepository: Repository<User>,
  ) {}

  /**
   * Busca un usuario por su correo electronico excluyendo la contraseña.
   * @param email Correo del usuario.
   * @returns El usuario encontrado o null.
   */
  async findByEmail(email: string): Promise<User | null> {
    return this.userRepository.findOne({
      where: { email: email.toLowerCase().trim() },
    });
  }

  /**
   * Busca un usuario por su correo incluyendo explicitamente el hash de la contraseña para autenticacion.
   * @param email Correo del usuario.
   * @returns El usuario con el campo passwordHash incluido o null.
   */
  async findByEmailWithPassword(email: string): Promise<User | null> {
    return this.userRepository
      .createQueryBuilder('user')
      .addSelect('user.passwordHash')
      .where('LOWER(user.email) = :email', { email: email.toLowerCase().trim() })
      .getOne();
  }

  /**
   * Busca un usuario por su identificador UUID.
   * @param id UUID del usuario.
   * @returns El usuario encontrado.
   * @throws NotFoundException si no existe.
   */
  async findById(id: string): Promise<User> {
    const user = await this.userRepository.findOne({ where: { id } });
    if (!user) {
      throw new NotFoundException(`Usuario con ID ${id} no encontrado`);
    }
    return user;
  }

  /**
   * Crea un nuevo registro de usuario en el sistema.
   * @param userData Datos parciales del usuario a persistir.
   * @returns El usuario persistido.
   */
  async create(userData: Partial<User>): Promise<User> {
    const user = this.userRepository.create({
      ...userData,
      email: userData.email?.toLowerCase().trim(),
    });
    return this.userRepository.save(user);
  }
}
